<?php
declare(strict_types=1);
namespace Nexus\Infrastructure\Persistence;
use Nexus\Domain\Prestamo\PrestamoRepository;use Nexus\Domain\ValueObject\Cedula;
final class PdoPrestamoRepository implements PrestamoRepository
{
    private \PDO $pdo;public function __construct(\PDO $p){$this->pdo=$p;}
    public function listar(Cedula $u,bool $g):array{$sql='SELECT p.id_prestamo,p.categoria,p.estado,p.fecha_solicitado,p.fecha_devolucion,p.recursos_solicitados,p.jornada,p.lugar_entrega,p.descripcion,p.comentario_resolucion,p.cedula,u.nombre,u.apellido,e.id_equipo,e.nombre_equipo FROM PRESTAMO p INNER JOIN USUARIO u ON u.cedula=p.cedula INNER JOIN EQUIPO e ON e.id_equipo=p.id_equipo WHERE p.esta_activo=1';$p=[];if(!$g){$sql.=' AND p.cedula=?';$p[]=$u->value();}$sql.=' ORDER BY p.id_prestamo DESC';$q=$this->pdo->prepare($sql);$q->execute($p);return $q->fetchAll(\PDO::FETCH_ASSOC);}
    public function diasMaximos():int{$v=$this->pdo->query("SELECT valor FROM CONFIGURACION_SISTEMA WHERE clave='dias_maximos_prestamo'")->fetchColumn();return (int)($v?:30);}
    public function crear(array $d,Cedula $u):array{$this->pdo->beginTransaction();try{$q=$this->pdo->prepare("INSERT INTO PRESTAMO(categoria,estado,fecha_solicitado,fecha_devolucion,recursos_solicitados,jornada,lugar_entrega,descripcion,cedula,id_equipo) VALUES(?,'Solicitado',CURDATE(),?,?,?,?,?,?,?)");$v=$this->pdo->prepare('INSERT INTO SOLICITA_PRESTAMO(cedula,id_prestamo) VALUES(?,?)');$equipo=$this->pdo->prepare("SELECT categoria_equipo,cantidad_del_equipo,esta_activo,estado_equipo FROM EQUIPO WHERE id_equipo=? FOR UPDATE");$ocupados=$this->pdo->prepare("SELECT COALESCE(SUM(CAST(SUBSTRING_INDEX(recursos_solicitados,' ',1) AS UNSIGNED)),0) FROM PRESTAMO WHERE id_equipo=? AND esta_activo=1 AND estado IN ('Solicitado','Activo')");$ids=[];foreach($d['recursos'] as $r){$equipo->execute([$r['idEquipo']]);$inventario=$equipo->fetch(\PDO::FETCH_ASSOC);if(!$inventario||(int)$inventario['esta_activo']!==1||in_array($inventario['estado_equipo'],['Baja','Mantenimiento'],true))throw new \Nexus\Shared\DomainException('El equipo seleccionado no esta disponible.',409);if($this->normalizarCategoria($inventario['categoria_equipo'])!==$this->normalizarCategoria($d['categoria']))throw new \Nexus\Shared\DomainException('El equipo seleccionado no pertenece a la categoria elegida.',409);preg_match('/^(\d+)\s/u',$r['descripcion'],$m);$solicitados=(int)($m[1]??0);$ocupados->execute([$r['idEquipo']]);$disponibles=(int)$inventario['cantidad_del_equipo']-(int)$ocupados->fetchColumn();if($solicitados<1||$solicitados>$disponibles)throw new \Nexus\Shared\DomainException('No hay suficientes equipos disponibles para la cantidad solicitada.',409);$q->execute([$d['categoria'],$d['fecha'],$r['descripcion'],$d['jornada'],$d['ubicacion'],$d['detalle'],$u->value(),$r['idEquipo']]);$id=(int)$this->pdo->lastInsertId();$v->execute([$u->value(),$id]);$ids[]=$id;}$this->pdo->commit();return $ids;}catch(\Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
    public function baja(int $id):bool{$q=$this->pdo->prepare("UPDATE PRESTAMO SET esta_activo=0,estado='Cancelado' WHERE id_prestamo=? AND esta_activo=1");$q->execute([$id]);return $q->rowCount()===1;}
    public function comentar(int $id,string $c):bool{$q=$this->pdo->prepare("UPDATE PRESTAMO SET comentario_resolucion=? WHERE id_prestamo=? AND estado IN ('Activo','Devuelto','Cancelado')");$q->execute([$c,$id]);return $q->rowCount()===1;}
    private function normalizarCategoria(string $valor):string{$valor=iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$valor)?:$valor;$valor=strtolower($valor);$valor=preg_replace('/[^a-z0-9]+/',' ',trim($valor))??$valor;$valor=preg_replace('/\b([a-z0-9]{3,})s\b/','$1',$valor)??$valor;return trim($valor);}
    public function cambiarEstado(int $id,string $e):bool{$q=$this->pdo->prepare('UPDATE PRESTAMO SET estado=? WHERE id_prestamo=?');$q->execute([$e,$id]);if($q->rowCount())return true;$q=$this->pdo->prepare('SELECT 1 FROM PRESTAMO WHERE id_prestamo=?');$q->execute([$id]);return (bool)$q->fetchColumn();}
}
